import zipfile
import re

files = ['DAMOP.pptx', 'paper_file_1.docx', 'paper_file_2.docx']

for filename in files:
    print(f"=== {filename} ===")
    try:
        with zipfile.ZipFile(f'/root/papers/all/{filename}', 'r') as z:
            content = ""
            if filename.endswith('.docx'):
                xml = z.read('word/document.xml').decode('utf-8')
                content = re.sub('<[^>]*>', ' ', xml)
            elif filename.endswith('.pptx'):
                # pptx has slides in ppt/slides/slideX.xml
                # we just read all xmls found or just a few
                for name in z.namelist():
                    if name.startswith('ppt/slides/slide'):
                        xml = z.read(name).decode('utf-8')
                        content += re.sub('<[^>]*>', ' ', xml)
            print(content[:500])
    except Exception as e:
        print(e)
    print("\n")

